  'Tem gente pedindo a cabeça do técnico do {clube}. A organizada embarca?': {es:'Hay gente pidiendo la cabeza del técnico del {clube}. ¿La barra se suma?', en:"People are calling for {clube}'s manager's head. Is the firm on board?"},
  'E o trabalho do técnico do {clube}?': {es:'¿Y el trabajo del técnico del {clube}?', en:"And the job {clube}'s manager is doing?"},
  'Bancar o técnico': {es:'Bancar al técnico', en:'Back the manager'},
