  'Não comentar': {es:'No comentar', en:'No comment'},
  'não comentou a confusão': {es:'no comentó el lío', en:'made no comment on the trouble'},

  'Saiu a lista pra temporada e a impressão é que o elenco do {clube} piorou — {de} pra {para} de força. A torcida cobra reforço?':
    {es:'Salió la lista para la temporada y parece que el plantel del {clube} empeoró: de {de} a {para} de fuerza. ¿La barra exige refuerzos?', en:"The squad list for the season is out and it looks like {clube}'s squad got worse — from {de} to {para} strength. Does the firm demand signings?"},
  'Cobrar reforço na porta da diretoria': {es:'Exigir refuerzos en la puerta de la directiva', en:"Demand signings at the board's door"},
  'cobrou reforço pra temporada': {es:'exigió refuerzos para la temporada', en:'demanded signings for the season'},
  'Dizer que o que veio dá conta': {es:'Decir que lo que vino alcanza', en:"Say what's come in will do"},
  'bancou o elenco que a diretoria montou': {es:'bancó el plantel que armó la directiva', en:'backed the squad the board put together'},
  'Esperar a bola rolar': {es:'Esperar a que ruede la pelota', en:'Wait for the ball to roll'},
  'preferiu esperar a bola rolar': {es:'prefirió esperar a que ruede la pelota', en:'chose to wait for the ball to roll'},

  'O {clube} se reforçou pra temporada — no papel o elenco está melhor, {de} pra {para} de força. A torcida dá o crédito à diretoria?':
    {es:'El {clube} se reforzó para la temporada: en los papeles el plantel está mejor, de {de} a {para} de fuerza. ¿La barra le da el crédito a la directiva?', en:'{clube} have strengthened for the season — on paper the squad is better, {de} to {para} strength. Does the firm give the board credit?'},
  'Dar o crédito à diretoria': {es:'Darle el crédito a la directiva', en:'Give the board credit'},
  'deu o crédito da montagem à diretoria': {es:'le dio el crédito del armado a la directiva', en:'gave the board credit for the squad'},
